// 🧰 Escapa caracteres especiales en regex
function escapeRegex(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// 🧩 Función para extraer datos correctamente desde n8n
function extraerDatos(input) {
  let datos = input;
  if (Array.isArray(datos)) datos = datos[0];
  if (datos.json) datos = datos.json;
  if (datos.query) {
    if (typeof datos.query === "string") {
      try {
        datos = JSON.parse(datos.query);
      } catch (e) {
        throw new Error("Error al parsear query: " + e.message);
      }
    } else {
      datos = datos.query;
    }
  }
  return datos;
}

// 🧮 Función para buscar modelo
function detectarModelo(texto) {
  for (const modelo of MODELOS) {
    const modeloEscapado = escapeRegex(modelo);
    const regex = new RegExp(`\\b${modeloEscapado}\\b`, "i");
    if (regex.test(texto)) {
      return modelo;
    }
  }
  return null;
}

// 🧮 Función para buscar kilometraje
function detectarKilometraje(texto) {
  const match = texto.match(/(\d{1,3}(?:\.\d{3})*|\d+)\s*km/i);
  if (match) {
    const km = match[1].replace(/\./g, "");
    return parseInt(km, 10);
  }
  return null;
}

